import{_ as e,a0 as t,w as r,s as o,I as a,x as n,a1 as l,A as p,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"编译器简介： 在 Siri 前时代如何与计算机对话 | LCTT x X-CMD","titleTemplate":false,"description":"编译器简介： 在 Siri 前时代如何与计算机对话 | LCTT (201709) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"编译器简介： 在 Siri 前时代如何与计算机对话 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"编译器简介： 在 Siri 前时代如何与计算机对话 | LCTT (201709) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201709/20170813 An Intro to Compilers","title":"编译器简介： 在 Siri 前时代如何与计算机对话","tag":"201709","desc":""},"relativePath":"201709/20170813 An Intro to Compilers.md","filePath":"[post].md"}'),g={name:"201709/20170813 An Intro to Compilers.md"};function c(u,s,m,h,b,k){const i=t("Link");return r(),o("div",null,[s[36]||(s[36]=a("h1",{id:"编译器简介-在-siri-前时代如何与计算机对话",tabindex:"-1"},[n("编译器简介： 在 Siri 前时代如何与计算机对话 "),a("a",{class:"header-anchor",href:"#编译器简介-在-siri-前时代如何与计算机对话","aria-label":"Permalink to “编译器简介： 在 Siri 前时代如何与计算机对话”"},"​")],-1)),s[37]||(s[37]=a("p",null,[a("img",{src:"https://pbs.twimg.com/media/C_5qf8aXkAAvSXC.jpg",alt:"了解在编译器的世界里前端和后端的新意义"})],-1)),a("p",null,[s[1]||(s[1]=n("简单说来，一个",-1)),s[2]||(s[2]=a("ruby",null,[n("编译器"),a("rt",null,"compiler")],-1)),s[3]||(s[3]=n("不过是一个可以翻译其他程序的程序。传统的编译器可以把源代码翻译成你的计算机能够理解的可执行机器代码。（一些编译器将源代码翻译成别的程序语言，这样的编译器称为源到源翻译器或",-1)),s[4]||(s[4]=a("ruby",null,[n("转化器"),a("rt",null,"transpilers")],-1)),s[5]||(s[5]=n("。）",-1)),l(i,{href:"http://llvm.org/"},{default:p(()=>[...s[0]||(s[0]=[n("LLVM",-1)])]),_:1}),s[6]||(s[6]=n(" 是一个广泛使用的编译器项目，包含许多模块化的编译工具。",-1))]),s[38]||(s[38]=a("p",null,"传统的编译器设计包含三个部分：",-1)),s[39]||(s[39]=a("p",null,[a("img",{src:"https://nicoleorchard.com/img/blog/compilers/compiler1.jpg",alt:""})],-1)),a("ul",null,[a("li",null,[s[8]||(s[8]=a("ruby",null,[n("前端"),a("rt",null,"Frontend")],-1)),s[9]||(s[9]=n("将源代码翻译为",-1)),s[10]||(s[10]=a("ruby",null,[n("中间表示"),a("rt",null,"intermediate representation ")],-1)),s[11]||(s[11]=n(" (IR)* 。",-1)),l(i,{href:"http://clang.llvm.org/"},{default:p(()=>[...s[7]||(s[7]=[n("clang",-1)])]),_:1}),s[12]||(s[12]=n(" 是 LLVM 中用于 C 家族语言的前端工具。",-1))]),a("li",null,[s[14]||(s[14]=a("ruby",null,[n("优化器"),a("rt",null,"Optimizer")],-1)),s[15]||(s[15]=n("分析 IR 然后将其转化为更高效的形式。",-1)),l(i,{href:"http://llvm.org/docs/CommandGuide/opt.html"},{default:p(()=>[...s[13]||(s[13]=[n("opt",-1)])]),_:1}),s[16]||(s[16]=n(" 是 LLVM 的优化工具。",-1))]),a("li",null,[s[18]||(s[18]=a("ruby",null,[n("后端"),a("rt",null,"Backend")],-1)),s[19]||(s[19]=n("通过将 IR 映射到目标硬件指令集从而生成机器代码。",-1)),l(i,{href:"http://llvm.org/docs/CommandGuide/llc.html"},{default:p(()=>[...s[17]||(s[17]=[n("llc",-1)])]),_:1}),s[20]||(s[20]=n(" 是 LLVM 的后端工具。",-1))])]),s[40]||(s[40]=d(`<p>注：LLVM 的 IR 是一种和汇编类似的低级语言。然而，它抽离了特定硬件信息。</p><h3 id="hello-compiler" tabindex="-1">Hello, Compiler <a class="header-anchor" href="#hello-compiler" aria-label="Permalink to “Hello, Compiler”">​</a></h3><p>下面是一个打印 “Hello, Compiler!” 到标准输出的简单 C 程序。C 语法是人类可读的，但是计算机却不能理解，不知道该程序要干什么。我将通过三个编译阶段使该程序变成机器可执行的程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// compile_me.c</span></span>
<span class="line"><span>// Wave to the compiler. The world can wait.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main() {</span></span>
<span class="line"><span>  printf(&quot;Hello, Compiler!\\n&quot;);</span></span>
<span class="line"><span>  return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to “前端”">​</a></h4><p>正如我在上面所提到的，<code>clang</code> 是 LLVM 中用于 C 家族语言的前端工具。Clang 包含 <ruby>C 预处理器<rt>C preprocessor</rt></ruby>、<ruby>词法分析器<rt>lexer</rt></ruby>、<ruby>语法解析器<rt>parser</rt></ruby>、<ruby>语义分析器<rt>semantic analyzer</rt></ruby>和 <ruby>IR 生成器<rt>IR generator</rt></ruby>。</p><p><strong>C 预处理器</strong>在将源程序翻译成 IR 前修改源程序。预处理器处理外部包含文件，比如上面的 <code>#include &lt;stdio.h&gt;</code>。 它将会把这一行替换为 <code>stdio.h</code> C 标准库文件的完整内容，其中包含 <code>printf</code> 函数的声明。</p><p>通过运行下面的命令来查看预处理步骤的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>clang -E compile_me.c -o preprocessed.i</span></span></code></pre></div><p><strong>词法分析器</strong>（或<ruby>扫描器<rt>scanner</rt></ruby>或<ruby>分词器<rt>tokenizer</rt></ruby>）将一串字符转化为一串单词。每一个单词或<ruby>记号<rt>token</rt></ruby>，被归并到五种语法类别之一：标点符号、关键字、标识符、文字或注释。</p><p>compile_me.c 的分词过程：</p><p><img src="https://nicoleorchard.com/img/blog/compilers/lexer.jpg" alt=""></p><p><strong>语法分析器</strong>确定源程序中的单词流是否组成了合法的句子。在分析记号流的语法后，它会输出一个<ruby>抽象语法树<rt>abstract syntax tree</rt></ruby>（AST）。Clang 的 AST 中的节点表示声明、语句和类型。</p><p>compile_me.c 的语法树：</p><p><img src="https://nicoleorchard.com/img/blog/compilers/tree.jpg" alt=""></p><p><strong>语义分析器</strong>会遍历抽象语法树，从而确定代码语句是否有正确意义。这个阶段会检查类型错误。如果 <code>compile_me.c</code> 的 main 函数返回 <code>&quot;zero&quot;</code>而不是 <code>0</code>， 那么语义分析器将会抛出一个错误，因为 <code>&quot;zero&quot;</code> 不是 <code>int</code> 类型。</p><p><strong>IR 生成器</strong>将抽象语法树翻译为 IR。</p><p>对 compile_me.c 运行 clang 来生成 LLVM IR：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>clang -S -emit-llvm -o llvm_ir.ll compile_me.c</span></span></code></pre></div><p>在 <code>llvm_ir.ll</code> 中的 main 函数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>; llvm_ir.ll</span></span>
<span class="line"><span>@.str = private unnamed_addr constant [18 x i8] c&quot;Hello, Compiler!\\0A\\00&quot;, align 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>define i32 @main() {</span></span>
<span class="line"><span>  %1 = alloca i32, align 4 ; &lt;- memory allocated on the stack</span></span>
<span class="line"><span>  store i32 0, i32* %1, align 4</span></span>
<span class="line"><span>  %2 = call i32 (i8*, ...) @printf(i8* getelementptr inbounds ([18 x i8], [18 x i8]* @.str, i32 0, i32 0))</span></span>
<span class="line"><span>  ret i32 0</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>declare i32 @printf(i8*, ...)</span></span></code></pre></div><h4 id="优化程序" tabindex="-1">优化程序 <a class="header-anchor" href="#优化程序" aria-label="Permalink to “优化程序”">​</a></h4><p>优化程序的工作是基于其对程序的运行时行为的理解来提高代码效率。优化程序将 IR 作为输入，然后生成改进后的 IR 作为输出。LLVM 的优化工具 <code>opt</code> 将会通过标记 <code>-O2</code>（大写字母 <code>o</code>，数字 2）来优化处理器速度，通过标记 <code>Os</code>（大写字母 <code>o</code>，小写字母 <code>s</code>）来减少指令数目。</p><p>看一看上面的前端工具生成的 LLVM IR 代码和运行下面的命令生成的结果之间的区别：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>opt -O2 -S llvm_ir.ll -o optimized.ll</span></span></code></pre></div><p>在 <code>optimized.ll</code> 中的 main 函数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>optimized.ll</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@str = private unnamed_addr constant [17 x i8] c&quot;Hello, Compiler!\\00&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>define i32 @main() {</span></span>
<span class="line"><span>  %puts = tail call i32 @puts(i8* getelementptr inbounds ([17 x i8], [17 x i8]* @str, i64 0, i64 0))</span></span>
<span class="line"><span>  ret i32 0</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>declare i32 @puts(i8* nocapture readonly)</span></span></code></pre></div><p>优化后的版本中， main 函数没有在栈中分配内存，因为它不使用任何内存。优化后的代码中调用 <code>puts</code> 函数而不是 <code>printf</code> 函数，因为程序中并没有使用 <code>printf</code> 函数的格式化功能。</p><p>当然，优化程序不仅仅知道何时可以把 <code>printf</code> 函数用 <code>puts</code> 函数代替。优化程序也能展开循环并内联简单计算的结果。考虑下面的程序，它将两个整数相加并打印出结果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// add.c</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main() {</span></span>
<span class="line"><span>  int a = 5, b = 10, c = a + b;</span></span>
<span class="line"><span>  printf(&quot;%i + %i = %i\\n&quot;, a, b, c);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>下面是未优化的 LLVM IR：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@.str = private unnamed_addr constant [14 x i8] c&quot;%i + %i = %i\\0A\\00&quot;, align 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>define i32 @main() {</span></span>
<span class="line"><span>  %1 = alloca i32, align 4 ; &lt;- allocate stack space for var a</span></span>
<span class="line"><span>  %2 = alloca i32, align 4 ; &lt;- allocate stack space for var b</span></span>
<span class="line"><span>  %3 = alloca i32, align 4 ; &lt;- allocate stack space for var c</span></span>
<span class="line"><span>  store i32 5, i32* %1, align 4  ; &lt;- store 5 at memory location %1</span></span>
<span class="line"><span>  store i32 10, i32* %2, align 4 ; &lt;- store 10 at memory location %2</span></span>
<span class="line"><span>  %4 = load i32, i32* %1, align 4 ; &lt;- load the value at memory address %1 into register %4</span></span>
<span class="line"><span>  %5 = load i32, i32* %2, align 4 ; &lt;- load the value at memory address %2 into register %5</span></span>
<span class="line"><span>  %6 = add nsw i32 %4, %5 ; &lt;- add the values in registers %4 and %5\\. put the result in register %6</span></span>
<span class="line"><span>  store i32 %6, i32* %3, align 4 ; &lt;- put the value of register %6 into memory address %3</span></span>
<span class="line"><span>  %7 = load i32, i32* %1, align 4 ; &lt;- load the value at memory address %1 into register %7</span></span>
<span class="line"><span>  %8 = load i32, i32* %2, align 4 ; &lt;- load the value at memory address %2 into register %8</span></span>
<span class="line"><span>  %9 = load i32, i32* %3, align 4 ; &lt;- load the value at memory address %3 into register %9</span></span>
<span class="line"><span>  %10 = call i32 (i8*, ...) @printf(i8* getelementptr inbounds ([14 x i8], [14 x i8]* @.str, i32 0, i32 0), i32 %7, i32 %8, i32 %9)</span></span>
<span class="line"><span>  ret i32 0</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>declare i32 @printf(i8*, ...)</span></span></code></pre></div><p>下面是优化后的 LLVM IR：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@.str = private unnamed_addr constant [14 x i8] c&quot;%i + %i = %i\\0A\\00&quot;, align 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>define i32 @main() {</span></span>
<span class="line"><span>  %1 = tail call i32 (i8*, ...) @printf(i8* getelementptr inbounds ([14 x i8], [14 x i8]* @.str, i64 0, i64 0), i32 5, i32 10, i32 15)</span></span>
<span class="line"><span>  ret i32 0</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>declare i32 @printf(i8* nocapture readonly, ...)</span></span></code></pre></div><p>优化后的 main 函数本质上是未优化版本的第 17 行和 18 行，伴有变量值内联。<code>opt</code> 计算加法，因为所有的变量都是常数。很酷吧，对不对？</p><h4 id="后端" tabindex="-1">后端 <a class="header-anchor" href="#后端" aria-label="Permalink to “后端”">​</a></h4><p>LLVM 的后端工具是 <code>llc</code>。它分三个阶段将 LLVM IR 作为输入生成机器代码。</p><ul><li><strong>指令选择</strong>是将 IR 指令映射到目标机器的指令集。这个步骤使用虚拟寄存器的无限名字空间。</li><li><strong>寄存器分配</strong>是将虚拟寄存器映射到目标体系结构的实际寄存器。我的 CPU 是 x86 结构，它只有 16 个寄存器。然而，编译器将会尽可能少的使用寄存器。</li><li><strong>指令安排</strong>是重排操作，从而反映出目标机器的性能约束。</li></ul><p>运行下面这个命令将会产生一些机器代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>llc -o compiled-assembly.s optimized.ll</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>_main:</span></span>
<span class="line"><span>	pushq	%rbp</span></span>
<span class="line"><span>	movq	%rsp, %rbp</span></span>
<span class="line"><span>	leaq	L_str(%rip), %rdi</span></span>
<span class="line"><span>	callq	_puts</span></span>
<span class="line"><span>	xorl	%eax, %eax</span></span>
<span class="line"><span>	popq	%rbp</span></span>
<span class="line"><span>	retq</span></span>
<span class="line"><span>L_str:</span></span>
<span class="line"><span>	.asciz	&quot;Hello, Compiler!&quot;</span></span></code></pre></div><p>这个程序是 x86 汇编语言，它是计算机所说的语言，并具有人类可读语法。某些人最后也许能理解我。</p><hr><p>相关资源：</p>`,44)),a("ol",null,[a("li",null,[l(i,{href:"https://www.amazon.com/Engineering-Compiler-Second-Keith-Cooper/dp/012088478X"},{default:p(()=>[...s[21]||(s[21]=[n("设计一个编译器",-1)])]),_:1})]),a("li",null,[l(i,{href:"https://www.amazon.com/Getting-Started-LLVM-Core-Libraries/dp/1782166920"},{default:p(()=>[...s[22]||(s[22]=[n("开始探索 LLVM 核心库",-1)])]),_:1})])]),s[41]||(s[41]=a("hr",null,null,-1)),a("p",null,[s[24]||(s[24]=n("via: ",-1)),l(i,{href:"https://nicoleorchard.com/blog/compilers"},{default:p(()=>[...s[23]||(s[23]=[n("https://nicoleorchard.com/blog/compilers",-1)])]),_:1})]),a("p",null,[s[28]||(s[28]=n("作者：",-1)),l(i,{href:"https://nicoleorchard.com/"},{default:p(()=>[...s[25]||(s[25]=[n("Nicole Orchard",-1)])]),_:1}),s[29]||(s[29]=n(" 译者：",-1)),l(i,{href:"https://github.com/ucasFL"},{default:p(()=>[...s[26]||(s[26]=[n("ucasFL",-1)])]),_:1}),s[30]||(s[30]=n(" 校对：",-1)),l(i,{href:"https://github.com/wxy"},{default:p(()=>[...s[27]||(s[27]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[33]||(s[33]=n("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[31]||(s[31]=[n("LCTT",-1)])]),_:1}),s[34]||(s[34]=n(" 原创编译，",-1)),l(i,{href:"https://linux.cn/"},{default:p(()=>[...s[32]||(s[32]=[n("Linux中国",-1)])]),_:1}),s[35]||(s[35]=n(" 荣誉推出",-1))])])}const v=e(g,[["render",c]]);export{C as __pageData,v as default};
